def inv(a, n):
    t, new_t = 0, 1
    r, new_r = n, a
    while new_r != 0:
        quotient = r // new_r
        t, new_t = new_t, t - quotient * new_t
        r, new_r = new_r, r - quotient * new_r
    if r > 1:
        return 0
    if t < 0:
        t = t + n
    return t

def calc_expr(input, expr, n):
    r = 0
    for i in range(len(expr)):
        r += pow(input, expr[i], n)
    r %= n
    return r

def calc_expr_two_dim(input, expr, n):
    r = 1
    for i in range(len(expr)):
        r *= calc_expr(input, expr[i], n)
        r %= n
    return r

def rsa(c, n):
    left_1 = calc_expr_two_dim(c, left_public_1, n)
    right_1 = calc_expr(c, right_public_1, n)
    left_2 = calc_expr_two_dim(c, left_public_2, n)
    right_2 = calc_expr(c, right_public_2, n)
    left_1_inv = inv(left_1, n)
    x1 = (left_1_inv * right_1) % n
    left_2_inv = inv(left_2, n)
    x2 = (left_2_inv * right_2) % n
    return (x1 - x2) % n

i_hex = sys.argv[1]
i_int = int(i_hex, 16)
o_int = rsa(i_int, n)
o_bin = o_int.to_bytes(256, 'big', signed = False)
hash = sha256()
hash.update(o_bin)
print(hash.digest().hex(), end='')
